import { inject } from '@angular/core';
import {
  CanActivateFn,
  Router,
  UrlTree,
} from '@angular/router';
import { Observable, catchError, map, of } from 'rxjs';
import { AuthService } from '../services/auth.service';
import { UserRole } from '../models/user.model';

export const roleGuard =
  (roles: UserRole[]): CanActivateFn =>
  (): Observable<boolean | UrlTree> | boolean | UrlTree => {
    const authService = inject(AuthService);
    const router = inject(Router);

    const user = authService.currentUser();

    if (user && roles.includes(user.role)) {
      return true;
    }

    if (user && !roles.includes(user.role)) {
      return router.parseUrl(authService.defaultRouteFor(user.role).join(''));
    }

    return authService.checkSession().pipe(
      map((authenticated) => {
        if (authenticated && roles.includes(authenticated.role)) {
          return true;
        }

        if (authenticated) {
          return router.parseUrl(
            authService.defaultRouteFor(authenticated.role).join(''),
          );
        }

        authService.openModal();
        return router.parseUrl('/');
      }),
      catchError(() => {
        authService.openModal();
        return of(router.parseUrl('/'));
      }),
    );
  };
